import{_ as r,C as s,o,c as i,j as a,a as n,E as l,a6 as d}from"./chunks/framework.BHBQfcoO.js";const b=JSON.parse('{"title":"LCARdS 2026.04.25.1","description":"Screen effects, alert overlay auto-dismiss, templated colours, per-device and per-user settings.","frontmatter":{"version":"2026.04.25.1","date":"2026-04-25T00:00:00.000Z","status":"released","summary":"Screen effects, alert overlay auto-dismiss, templated colours, per-device and per-user settings.","breaking":false},"headers":[],"relativePath":"releases/2026.04.25.1.md","filePath":"releases/2026.04.25.1.md"}'),c={name:"releases/2026.04.25.1.md"};function u(h,e,m,g,p,f){const t=s("ReleaseMeta");return o(),i("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-04-25-1",tabindex:"-1"},[n("LCARdS 2026.04.25.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-04-25-1","aria-label":'Permalink to "LCARdS 2026.04.25.1"'},"​")],-1)),l(t),e[1]||(e[1]=d('<p>This release brings in some user requests/suggestions (keep them coming!), card improvements, a new core subsystem, a pile of fixes, and a major documentation update.</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h4 id="core-system-screen-effect-manager" tabindex="-1">(core system) Screen Effect Manager <a class="header-anchor" href="#core-system-screen-effect-manager" aria-label="Permalink to &quot;(core system) Screen Effect Manager&quot;">​</a></h4><p>New subsystem bringing full-screen composited visual effects to LCARdS.</p><ul><li>Provides a stackable 3-layer system (filter, colour, effect)</li><li>Create some interesting effects when used with Alert Overlay or browser_mod</li><li>Full HA service support (<code>lcards.trigger_effect</code> / <code>lcards.clear_effect</code>) or the browser console (<code>window.lcards.screenEffect.*</code>)</li></ul><h4 id="alert-overlay-enhancements" tabindex="-1">Alert Overlay Enhancements <a class="header-anchor" href="#alert-overlay-enhancements" aria-label="Permalink to &quot;Alert Overlay Enhancements&quot;">​</a></h4><p>The alert overlay now supports configurable auto-dismiss behaviour.</p><ul><li>Adds a configurable auto-dismiss mode to automatically clear the overlay after a timeout</li><li>Refactored to use Screen Effect Manager</li><li>New <strong>browser_mod integration</strong> documentation page covers how to integrate LCARdS alerts with browser_mod popups and browser-targeted automations</li></ul><h4 id="new-colour-features" tabindex="-1">New Colour Features <a class="header-anchor" href="#new-colour-features" aria-label="Permalink to &quot;New Colour Features&quot;">​</a></h4><h5 id="computed-colour-function-base" tabindex="-1">computed colour function: <code>base()</code> <a class="header-anchor" href="#computed-colour-function-base" aria-label="Permalink to &quot;computed colour function: `base()`&quot;">​</a></h5><ul><li>Resolves a colour against the <strong>pre-alert (baseline) palette</strong>, making it immune to alert-mode hue shifts: useful for UI elements that shouldn&#39;t change colour during an alert.</li></ul><h5 id="templated-colour-configs" tabindex="-1">Templated Colour Configs <a class="header-anchor" href="#templated-colour-configs" aria-label="Permalink to &quot;Templated Colour Configs&quot;">​</a></h5><ul><li>Jinja2/JS template support added to all state-based colour resolution keys (<code>color.active</code>, <code>color.default</code>, etc.).</li><li>Referenced entities are automatically tracked for state changes; also a new <code>triggers_update</code> config key forces template re-evaluation on specified entity IDs even if not directly referenced: similar to <code>custom-button-card</code>&#39;s same key</li><li>Thanks for reporting! (<a href="https://github.com/snootched/lcards/discussions/343" target="_blank" rel="noreferrer">discussion #343</a>)</li></ul><h4 id="card-interactive-mode" tabindex="-1">Card Interactive Mode <a class="header-anchor" href="#card-interactive-mode" aria-label="Permalink to &quot;Card Interactive Mode&quot;">​</a></h4><ul><li>Set <code>interactive: false</code> to suppress hover animations, cursor changes, and pressed feedback: useful for decorative or display-only cards</li><li>New <code>style.cursor</code> key overrides cursor style independently when interactive mode is on</li><li>Thanks for requesting! (<a href="https://github.com/snootched/lcards/discussions/343" target="_blank" rel="noreferrer">discussion #343</a> · <a href="https://github.com/snootched/lcards/issues/344" target="_blank" rel="noreferrer">#344</a>)</li></ul><h4 id="card-sizing-updates" tabindex="-1">Card Sizing Updates <a class="header-anchor" href="#card-sizing-updates" aria-label="Permalink to &quot;Card Sizing Updates&quot;">​</a></h4><ul><li>Fixed overflow when using <code>custom-layout-card</code> with <code>card_margin</code>: a <code>width: 100%</code> on <code>:host</code> was causing bleed outside margin boundaries</li><li>Initial size measurement now uses a double animation-frame delay to let ancestor layout styles settle first</li><li>Editor hints added for layout-card height configuration; details at <a href="/cards/common.html#sizing-inside-custom-layout-card">Sizing inside <code>custom:layout-card</code></a></li><li>A custom-patched version of <code>custom-layout-card</code> is available to fix the upstream <code>card_margin</code> bug</li></ul><h2 id="promoted-from-preview" tabindex="-1">Promoted from Preview <a class="header-anchor" href="#promoted-from-preview" aria-label="Permalink to &quot;Promoted from Preview&quot;">​</a></h2><h3 id="per-device-per-user-settings" tabindex="-1">Per-Device &amp; Per-User Settings <a class="header-anchor" href="#per-device-per-user-settings" aria-label="Permalink to &quot;Per-Device &amp; Per-User Settings&quot;">​</a></h3><p>A fully scoped-settings system for the backend is included. This enables persistent storage with APIs for per-user/per-device settings. The first feature to utilize this new system is the Sound system.</p><h4 id="per-device-per-user-sound" tabindex="-1">Per-Device &amp; Per-User Sound <a class="header-anchor" href="#per-device-per-user-sound" aria-label="Permalink to &quot;Per-Device &amp; Per-User Sound&quot;">​</a></h4><p>Sound settings can be configured independently per browser session and per HA user. A wall-mounted kiosk can run at lower volume than a desktop; a specific user can disable sounds entirely without affecting anyone else. All of this is configurable centrally from the Config Panel: no need to make changes from the target device.</p><h4 id="users-devices-management" tabindex="-1">Users &amp; Devices Management <a class="header-anchor" href="#users-devices-management" aria-label="Permalink to &quot;Users &amp; Devices Management&quot;">​</a></h4><p>Each browser/device receives a stable unique identity that persists across page reloads. Devices can be given friendly display names (&quot;Kitchen Tablet&quot;, &quot;Bedroom Tablet&quot;) for easy to use referencing.</p><p>A new <strong>Users &amp; Devices</strong> tab appears in the LCARdS Config Panel that provides a central view of all registered devices and users with stored scoped settings, and provides the ability to manage their overrides without needing to be on the target device.</p><h4 id="targeted-ha-services" tabindex="-1">Targeted HA Services <a class="header-anchor" href="#targeted-ha-services" aria-label="Permalink to &quot;Targeted HA Services&quot;">​</a></h4><p>All <code>lcards.*</code> HA services (alert modes, clear alert, reload page, log level) can now be targeted at specific devices or users rather than broadcasting to all sessions. Four targeting fields are supported:</p><ul><li><code>target_device_ids</code>: target by device/browser UUID</li><li><code>target_user_ids</code>: target by HA user ID</li><li><code>target_device_names</code>: target by friendly device name (case-insensitive, resolved server-side)</li><li><code>target_user_names</code>: target by HA user display name (case-insensitive, resolved server-side)</li></ul><p>Omitting all fields broadcasts to everyone: fully backward-compatible with existing automations.</p><h4 id="targeted-alert-modes" tabindex="-1">Targeted Alert Modes <a class="header-anchor" href="#targeted-alert-modes" aria-label="Permalink to &quot;Targeted Alert Modes&quot;">​</a></h4><p>Alert modes (red/yellow/blue alert etc.) can now be triggered on individual devices or users without changing the global alert state. A red alert on the kitchen tablet doesn&#39;t affect any other screen, and clearing it stays local.</p><h2 id="updates-fixes" tabindex="-1">Updates &amp; Fixes <a class="header-anchor" href="#updates-fixes" aria-label="Permalink to &quot;Updates &amp; Fixes&quot;">​</a></h2><ul><li><strong>(Documentation)</strong> Major overhaul: improved navigation and a simpler getting-started flow</li><li><strong>(Slider)</strong> Fixed text zones for the <code>shaped</code> preset; all slider presets updated to use theme tokens for colour</li><li><strong>(AlertMode)</strong> Fixed startup timing to properly capture CSS variables and apply in-progress alert modes on load; added retry logic for transient init states</li><li><strong>(ThemeManager)</strong> Token override events are now debounced: prevents all dashboard cards re-processing simultaneously</li><li><strong>(DataSource)</strong> Removed deprecated <code>subscribeOverlay()</code> and overlay subscription infrastructure</li><li><strong>(StylePresetManager)</strong> Removed dead CSS utility class generation code</li><li><strong>(DeviceIdentityManager)</strong> Multi-tier UUID generation fallback for non-SSL sessions where Web Crypto API is unavailable</li><li><strong>(CSS/Tokens)</strong> Extensive cleanup of font and colour variable references across components</li><li><strong>(CI/Build)</strong> CSS variable validation is now gated in the build pipeline: <code>--lcars-*</code> tokens validated against the live HA-LCARS theme; <code>--lcards-*</code> vars and <code>theme:</code> paths validated from call sites to declarations</li><li><strong>(MSD Studio)</strong> Many fixes and layout/zoom enhancements</li></ul><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.04.13.1...2026.04.25.1" target="_blank" rel="noreferrer">2026.04.13.1...2026.04.25.1</a></p>',35))])}const y=r(c,[["render",u]]);export{b as __pageData,y as default};
